from math import gcd

MOD = 998244353

def lcm(a, b):
    return a * b // gcd(a, b)

def inverse_mod(exp):
    return pow(exp, MOD - 2, MOD)

def factorial_mod(n):
    current = 1
    for i in range(2, n + 1):
        current = (current * i) % MOD
    return current

def catalan_number(n):
    return ((factorial_mod(2 * n)) // (factorial_mod(n+1) * factorial_mod(n // 2 + 1)) % MOD)

def fibonacci_number(n):
    fibonacci = [0] * (n + 1)
    fibonacci[1] = 1
    for i in range(2, n + 1):
        fibonacci[i] = (fibonacci[i-1] + fibonacci[i-2]) % MOD
    return fibonacci[n]

def mek_merged_segments_level(n, a):
    if n == 1:
        return [0]
    root = [a[0]]
    merged = False
    segment_size = 0
    for i in range(1, n):
        if i % 2 == 1 and i+1 < n:
            if a[i] >= a[i + 1]:
                if root[-1] > a[i]:
                    root[-1], root[-2] = a[i], root[-1]
                    segment_size *= 2
                elif root[-1] < a[i]:
                    root[-1] = a[i]
                    segment_size += 1
        elif i % 2 == 0 and i < n-1:
            if a[i] > a[i + 1]:
                if root[-1] > a[i]:
                    root[-1], root[-2] = a[i], root[-1]
                    segment_size *= 2
                elif root[-1] < a[i]:
                    root[-1] = a[i]
                    segment_size += 1
        else:
            merged = True
    if merged:
        root.append(a[i])
        segment_size += 1
    return factorial_mod(segment_size), catalan_number(segment_size)

def count_ways(matrix_size, segment_size, odd_count, mod):
