def flip_grid(H, W, S):
    input_rectangles = [[[] for _ in range(W)] for _ in range(H)]
    for i in range(H):
        for j in range(W):
            input_rectangles[i][j] = S[i][j] == '#'
    return input_rectangles

def maximize_area(grid):
    max_area, ml, mr, cl, cr = 0, len(grid), len(grid[0]), grid, 0

    def area(h1, w1, h2, w2):
        for i in range(h1, h2):
            for j in range(w1, w2):
                grid[i][j] = not grid[i][j]
        mul, cur = 1, 1
        for h in range(h1, h2):
            for w in range(w1, w2):
                if grid[h][w]:
                    mul *= cur
                    cur = 1
                else:
                    cur *= 1
        return mul if mul > 0 else 0

    for rowlist in grid:
        for i in range(1, len(rowlist)):
            rowmerge_sum = -rowlist[0] + sum(rowlist[i:])
            ml = min(ml, i)  # left mc
            CR = rowmerge_sum - (i * rowlist[i])

            cl = max(cl, i)  # right mc
            for col in range(i, len(rowlist)):
                cr = max(cl, col) if CR + rowlist[col] > CR else cr
                area1, area2 = 1 - (sum(rowlist[i:len(rowlist) - col + 1])), 1 - (sum(col))
                area1, area2 = area1 * area2, area1 or area2
                max_area = max(max_area, area1, area2, area(ml, cl, mr, cr))

    mlleftsum = [-sum(row) for row in grid]  # mlleftsum[i] = sum(example.grid[0], example.grid[1], ..., example.grid[i])
    for i in range(1, len(mlleftsum)):
        max_area = max(max_area, mlleftsum[i], mlleftsum[i] + mlleftsum[i - 1] - sum(grid[i + 1:]))
    max_area = max(max_area, max(max_area, sum(grid)))

    return max_area

