def count_paintings(N, M, conditions):
    mod = 10**9 + 7
    dp = [1] * (N + 1)
    dp[0] = 1  # Base case: no color used to paint the first square

    for _ in range(M):
        next_dp = [0] * (N + 1)
        for i in range(1, N):
            if dp[i] == 0:
                continue
            for j in range(3):
                for k in range(i + 1, N + 1):
                    if dp[k]:
                        condition = [
                            1 if dp[i - 1] == 0 else dp[i - 1],
                            1 if dp[k - 1] == 0 else dp[k - 1],
                            j
                        ]
                        if all(condition[i] <= condition[i + 1] for i in range(len(condition))):
                            next_dp[k] = (next_dp[k] + dp[i]) % mod
        dp = next_dp

    return dp[N], dp

