import sys

def solve(n, m, edges):
    # Implementation of the Floyd-Warshall algorithm
    INF = 10**10
    dist = [[INF]*n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0
    for u, v, cost in edges:
        dist[u-1][v-1] = min(dist[u-1][v-1], cost)
        dist[v-1][u-1] = min(dist[v-1][u-1], cost)

    low, stack = [INF]*n, [0]*(n**2+1)
    for i in range(n):
        low[i] = dist[i][i]
        stack[0] = i
        for j in range(n):
            for k in range(n):
                dist[j][k] = min(dist[j][k], dist[j][i] + dist[i][k])
    for i in range(n):
