    for i in range(n):
        for j in range(m):
            if warehouse[i][j] == "Y":
                q.append((i, j, "Y"))
            if warehouse[i][j] == "B":
                q.append((i, j, "B"))
                target = (i, j)
    path.append("LOAD")

    def is_valid(x, y):
        return 0 <= x < n and 0 <= y < m and warehouse[x][y] in ".YB"

    while q and not found:
        loader, load, c = q.popleft()
        if (loader, load, c) == target:
            found = True
            continue

        if c == "Y":
            if not is_valid(loader - 1, load):
                q.append((loader - 1, load, "N"))
            else:
                q.append((loader - 1, load, "S"))

        elif c == "B":
            load += 1
            if not is_valid(loader + 1, load):
                q.append((loader + 1, load, "W"))
            else:
                q.append((loader + 1, load, "E"))

        direction = {
            "Y": "S",
            "B": "N",
            "W": "N",
            "E": "W"
        }
        if direction[c] == "W":
            q.append((load - 1, loader, direction[c]))
        elif direction[c] == "S":
            q.append((loader, load + 1, direction[c]))
        elif direction[c] == "N":
            q.append((load - 1, loader, direction[c]))
        elif direction[c] == "E":
            q.append((loader, load + 1, direction[c]))

        if "B" in warehouse[load]:
            path.append("B")
        if "Y" in warehouse[load]:
            path.append("load")
        path.append("move")

    if not found:
        return "NO"

    return "YES\n".join(path)

