    while any(x != 'a' for x in s) and any(y != 'b' for y in t):
        mismatched_chars = dict()
        for i in range(min(len(s), len(t))):
            if s[i] != 'a' and t[i] != 'b':
                mismatched_chars[s[i]] = i + 1
                if s[i] not in mismatched_chars:
                    mismatched_chars['b'] = i + 1
                    break
                if t[i] not in mismatched_chars:
                    mismatched_chars['a'] = i + 1
                    break
        if len(mismatched_chars) < 2:
            break
        if mismatched_chars['a'] == mismatched_chars['b']:
            operation_count += mismatched_chars['a']
            del mismatched_chars['a'], mismatched_chars['b']
        else:
            index1, index2 = sorted(mismatched_chars.items())
            operation_count += mismatched_chars[index1[0]]
            del mismatched_chars[index1[0]], mismatched_chars[index2[0]]
            if mismatched_chars['a'].endswith(mismatched_chars['b']):
                operation_count += len(mismatched_chars)
            else:
                operation_count += mismatched_chars['b'] - mismatched_chars['a'] - 1
        s = s[:mismatched_chars['a'] - 1] + 'a' + s[mismatched_chars['a'] - 1:min(mismatched_chars['a'], mismatched_chars['b'])][::-1] + s[min(mismatched_chars['a'], mismatched_chars['b']):]
        t = t[:mismatched_chars['b'] - 1] + 'b' + t[mismatched_chars['b'] - 1:min(mismatched_chars['a'], mismatched_chars['b'])][::-1] + t[min(mismatched_chars['a'], mismatched_chars['b']):]
