import math
from itertools import combinations

MOD = 998244353

def extend_gcd(a, b):
    """Extended Euclidean Algorithm to find modular inverse."""
    x0, y0 = 1, 0
    x1, y1 = 0, 1
    while b:
        q = a // b
        a, b = b, a % b
        x0, x1 = x1, x0 - q * x1
        y0, y1 = y1, y0 - q * y1
    return pow(a, MOD - 2, MOD)

def modular_inverse(y):
    """Modular inverse function."""
    return extend_gcd(y, MOD)[1]

def is_prime(n):
    """Miller_Rabin test function for primality test."""
    sqrt_n = int(math.sqrt(n))
    for i in range(sqrt_n):
        a = (10 + i) % n
        remainder = pow(a, i + 1, a * i + 1)
        while remainder != 1:
            if remainder != n - 1:
                poly = remainder - n + 1
                a = pow(a, 2, a * i + 1)
                if a * i + 1 % poly == 0: 
                    return False
            remainder -= 1
    return True

def prime_factors(n):
    """Print the prime factors of a number."""
    results = list()
    d, n = divmod(n, 2)
    results.append(2)
    while d:
        n, base = divmod(n, d)
        results.append(base)
        d, n = divmod(n, 2)
    if n == 1:
        results.append(n)
    return results

def counts_combs(r, n, MOD):
    """Finds the count of combinations. Computes (n + r - 1) choose r % MOD."""
    if n - r < r:
        return 0
    else:
        return pow(math.factorial(r) * pow(factorial(n - 1), modular_inverse(factorial(r - 1))).q, modular_inverse(MOD), MOD)

