    for u, v in edges:
        tree[u].add(v)
        tree[v].add(u)
    return tree

def dfs(tree, v, visited, parent, far, mx):
    for neighbor in tree[v]:
        if neighbor == parent:
            continue
        dfs(tree, neighbor, visited, v, far[neighbor], mx)
        mx[v] += max(dfs(tree, neighbor, visited, v, far, mx), mx[neighbor])
    mx[v] = 0

def solve(tree, n):
    visited = [False] * (n + 1)
    far = [0] * (n + 1)
    dfs(tree, 1, visited, -1, far, far)
    mins = max(far[1:-1]) + 1
    vars = set()
    append(vars, range(n))
    moves = []
    while len(vars) > 2:
        m = ((1, i, sorted(vars)[i + 1]) for i in range(n + 1, n - 1) if 0 in vars and far[i] > len(vars) - n - 2)
        if m != []:
            moves.append(m)
        vars = {i | set(vars) for min_vertex, min_flow, set_vertex in vars}
        for var in vars:
            visited[var[0]] = True
            for neighbor in tree[var[0]]:
                if neighbor != var[0] + 1:
                    if vars & set([var[0], neighbor, neighbor + 1]):
                        vars.remove(var)
                        vars.update([i | set(vars) for i in vars])
                        break
    moves = sorted(moves, key=lambda x: x[-1])
    return moves + [" ".join(map(str, i)) for i in vars if len(i) == 2]

if __name__ == "__main__":
    sys.stdin.readline()
    n = int(sys.stdin.readline())
    edges = [*map(int, sys.stdin.readline().split())[:-1]]
    tree = build_tree(edges)
    print(len(solve(tree, n)))
