import sys

def minimize_xor_xor(a, b):
    count = 0
    for i in range(len(a)):
        if a[i] > b[i]:
            count += a[i] - b[i]
    return count

def minimize_operations(n, a, b):
    min_operations = float('inf')
    for i in range(1 << n):
        temp_a = [0] * n
        for j in range(n):
            if (i >> j) & 1:
                temp_a[j] = a[j]
            else:
                temp_a[j] = b[j]
        min_operations = min(min_operations, minimize_xor_xor(a, temp_a))
    return min_operations

def solve_max_sum_xor_xor(n, a, b):
    total_xor = sum(a) ^ sum(b)
    if total_xor == 0:
        return 0
    return n - minimize_operations(n, a, b)

