def find_smallest_sequence(name):
    stack = []
    for char in name:
        if '0' <= char <= '9':
            stack.append(int(char))
    return stack

def is_feasible(seq):
    variables = set(seq)
    variables.add(0)
    variables.add(9)
    variables = sorted(variables)
    for i in range(1, len(variables)):
        if variables[i] - variables[i-1] > 1:
            return False
    return True

def feasible_sequence():
    seq = []
    while seq[-1] < 9:
        seq.append(0)
    seq.append(9)
    seq = find_smallest_sequence("".join(str(i).rjust(3, "0") for i in seq))
    if is_feasible(seq):
        return seq
    return False

result = feasible_sequence()
if result:
    print(" ".join(str(i) for i in result))
else:
